import{_ as t,V as l,W as d,Y as e,a0 as i,Z as p,X as n,F as o}from"./framework-9f272d12.js";const r={},g=e("h1",{id:"吃灰十年的-kindle-被-codex-一个技能改成了微信读书机",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#吃灰十年的-kindle-被-codex-一个技能改成了微信读书机","aria-hidden":"true"},"#"),i(" 吃灰十年的 Kindle，被 Codex 一个技能改成了微信读书机")],-1),c=e("h2",{id:"_01、引子-一篇-workbuddy-的文章-把我那台-kindle-想起来了",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#_01、引子-一篇-workbuddy-的文章-把我那台-kindle-想起来了","aria-hidden":"true"},"#"),i(" 01、引子：一篇 WorkBuddy 的文章，把我那台 Kindle 想起来了")],-1),s={href:"https://skillhub.cn/skills/user_b8af0005/kindle-jailbreak-weread",target:"_blank",rel:"noopener noreferrer"},_=n('<p>看完的第一反应不是「AI 真厉害」，而是想起了我那块在书架上吃灰快十年的 Kindle。毕业工作之后，我就没怎么正经用过它。亚马逊中国区电子书店一关，这台机器直接从阅读器退化成了泡面盖。机器没坏，屏幕没坏，电池甚至还能撑几天，但它离我的生活确实越来越远了。</p><p>最近在做一个 native 阅读 App 的间隙，我把这台吃灰的 Kindle 捞出来试了试，看能不能再盘活一下。毕竟上下班通勤时，这种轻量电纸书的阅读体验，确实比举着手机舒服不少。</p><p>很早就知道 Kindle 可以越狱，网上教程一抓一大把，闲鱼上甚至还有付费服务。但真要自己动手，型号、固件、越狱包各说各话，看一圈下来比刷机还累，花的时间精力少不了。正好把之前看到的文章翻出来，捞出 Skill，剩下的全交给 Codex，抱着「成不成无所谓」的态度试了试，结果居然还挺不错。</p><h2 id="_02、这次没照着教程手搓-而是让-codex-跑-skill" tabindex="-1"><a class="header-anchor" href="#_02、这次没照着教程手搓-而是让-codex-跑-skill" aria-hidden="true">#</a> 02、这次没照着教程手搓，而是让 Codex 跑 skill</h2><p>这次全过程，不研究 Skill，也不管具体方案，就一个「全托管」，直接让 Codex 开干。反正最坏的结果也就是变砖，而它现在和砖的区别也不大。</p><figure><img src="https://imgbed.ppai.top/file/1793606118370_at01.jpg" alt="at01.jpg" tabindex="0" loading="lazy"><figcaption>at01.jpg</figcaption></figure><p>整个过程比想象中顺利，Codex 很快就给出了执行方案。</p><figure><img src="https://imgbed.ppai.top/file/1793606268684_at02.jpg" alt="at02.jpg" tabindex="0" loading="lazy"><figcaption>at02.jpg</figcaption></figure><p>接下来就是等待。Codex 会按 Skill 里的约束，先备份、准备越狱、预占存储空间，再让我执行设备侧的操作，最后重启。我负责的部分基本就是「点一下」和「等」，技术含量约等于给微波炉按开始键。</p><p>事后看，完整流程是 0 到 8 步。</p><figure><img src="https://imgbed.ppai.top/file/1793614328483_image.png" alt="image.png" tabindex="0" loading="lazy"><figcaption>image.png</figcaption></figure><p>分工写得也很清楚，电脑侧的事归 Codex，设备侧的点按、选择、扫码归我。Agent 负责干脏活，我负责在屏幕上戳来戳去。</p><p>整个过程中，我需要干的就两件事：重启，以及访问网页下载 <code>jailbreak</code>。这玩意儿具体在干啥，我也没细看，反正 Codex 让我点，我就点，主打一个盲目信任。当然，友情提醒一句，不了解脚本作用的话，别随便下载网上的脚本🤣。</p><p>当然，过程也不是一帆风顺，我遇到了两个问题。</p><ol><li>设备空间不够、读写较慢：机器太老，存储只有 4G，得先把旧内容清一清，最后堪堪够用（预留 80M+）。4G 的存储，装完系统就所剩无几，清空间的时候像在给一间老房子腾地方。</li><li>在浏览器里点了下载，设备没有自动重启。正常情况下，下载完会自动重启，然后书架上会多出一本 <code>JAILBROKEN</code> 标记书。我当时的第一反应是：完了，是不是被我点坏了。</li></ol><p>问了 Codex 一句，它让我下载完再观察 2 分钟。……大概率还是设备太拉胯，响应慢。2 分钟，对这台机器来说可能只是刚睡醒。</p><figure><img src="https://imgbed.ppai.top/file/1793606919512_at03.jpg" alt="at03.jpg" tabindex="0" loading="lazy"><figcaption>at03.jpg</figcaption></figure><p>重启成功后，书架上会出现一个 <code>KOReader.sh</code> 脚本，点进去就是 KOReader。再到工具里切换成「觅阅」桌面，微信读书才算真正跑起来。到这一步，这台吃灰十年的机器终于有点像台阅读器了。</p><h2 id="_03、能用-但不代表好用" tabindex="-1"><a class="header-anchor" href="#_03、能用-但不代表好用" aria-hidden="true">#</a> 03、能用，但不代表好用</h2><p>实际用起来，微信读书确实能上了。书架在，进度在，划线和想法也在。手机扫码登录一次，后面基本不用再管。那一刻还挺有成就感，感觉像给老爷车换了个新发动机。</p><p>但这台机器的硬件属实有点拉胯。打开觅阅桌面要等，切换书籍要等，下载也慢；最离谱的是，阅读时调个字号，它直接弹「设备可用内存空间不够，为了避免崩溃拒绝执行」。调个字号而已，至于吗？于是我又把 Codex 叫了回来，让它上网查一圈，有没有更轻的桌面。</p><figure><img src="https://imgbed.ppai.top/file/1793607233290_at04.jpg" alt="at04.jpg" tabindex="0" loading="lazy"><figcaption>at04.jpg</figcaption></figure><p>Codex 查回来的方案是 SimpleUI。名字听着像某个极简风主题，实际上也差不多。</p><p>SimpleUI 是一个免费开源的 KOReader 界面插件。它不替代 KOReader，也没有微信读书接口，只把 KOReader 原来的文件管理器界面换成一个更清爽的主页，外加底部导航栏、顶部状态栏、阅读统计和快捷操作。一句话，它管脸，不管内容。</p><blockquote><p>额外说一句，KOReader 的原生界面是真够质朴的，质朴到让我想起了十年前的安卓平板。</p></blockquote><p>换成 SimpleUI 之后，最直观的感受是，这才像个阅读器该有的样子，简洁、直观，不跟你绕弯子。</p><figure><img src="https://imgbed.ppai.top/file/1793613703594_at05.jpg" alt="at05.jpg" tabindex="0" loading="lazy"><figcaption>at05.jpg</figcaption></figure><p>阅读界面的设置比 Kindle 原生那套丰富不少，字体、行距、页边距都能调。Kindle 原生设置像是「够用就行」，KOReader 则是「你想调什么都有」。</p><figure><img src="https://imgbed.ppai.top/file/1793613701299_at06.jpg" alt="at06.jpg" tabindex="0" loading="lazy"><figcaption>at06.jpg</figcaption></figure><p>待机页面也能自定义，比如换上我自己阅读器的 logo（树懒阅读🤣）。折腾到这一步，已经有点「不务正业」的快乐了。</p><figure><img src="https://imgbed.ppai.top/file/1793613706895_at07.jpg" alt="at07.jpg" tabindex="0" loading="lazy"><figcaption>at07.jpg</figcaption></figure><p>需要明确一点，SimpleUI 不是微信读书客户端。它只能索引本地文件，读不出微信云书架，所以想用微信读书，还是得切回「觅阅」桌面。装个皮肤就想白嫖微信书库，属于想多了。</p><h2 id="_04、结尾再说一句" tabindex="-1"><a class="header-anchor" href="#_04、结尾再说一句" aria-hidden="true">#</a> 04、结尾再说一句</h2><p>如果只用本地阅读，原来的 Kindle 其实就够了，为什么还要折腾这一圈？问得好，我也这么问过自己。</p><p>核心的出发点就是看到了这个 Skill，觉得可以低成本试一波，毕竟也没什么损失。本来还想再进一步，装个安卓阅读 App，结果发现还得刷 Android 系统，还是 5.x 的版本。5.x 的安卓，放到今天连很多 App 的安装包都嫌弃它。想想这台 Kindle 的性能，算了。</p><figure><img src="https://imgbed.ppai.top/file/1793614188075_at08.jpg" alt="at08.jpg" tabindex="0" loading="lazy"><figcaption>at08.jpg</figcaption></figure><p>最后的最后，再感慨一句，越狱后的效果确实不错，但这台 Kindle 最终的归宿，大概率还是回书架上吃灰。毕竟手机还是更香一点🙂。折腾一上午，换来一个「好像也行，但我还是用手机」的结局。。。</p>',37),f={href:"https://skillhub.cn/skills/user_b8af0005/kindle-jailbreak-weread",target:"_blank",rel:"noopener noreferrer"};function h(u,b){const a=o("ExternalLinkIcon");return l(),d("div",null,[g,c,e("p",null,[i("前阵子刷到一篇文章，作者用 WorkBuddy 把自己的 Kindle 越狱后刷上了微信读书，文末还留了一个 Skill 的入口："),e("a",s,[i("https://skillhub.cn/skills/user_b8af0005/kindle-jailbreak-weread"),p(a)])]),_,e("blockquote",null,[e("p",null,[i("想试试的小伙伴，可以直接用 "),e("a",f,[i("https://skillhub.cn/skills/user_b8af0005/kindle-jailbreak-weread"),p(a)]),i(" 这个 Skill 开干。友情提示，折腾有风险，变砖别找我🤣")])])])}const x=t(r,[["render",h],["__file","03.吃灰十年的Kindle-被Codex一个技能改成了微信读书机.html.vue"]]);export{x as default};
